{"files":[{"path":"src/occupationalInfo/date.mjs","content":"function parseCalendarDate(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const year = Number(value.slice(0, 4));
  const month = Number(value.slice(5, 7));
  const day = Number(value.slice(8, 10));
  if (month < 1 || month > 12) return null;
  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > daysInMonth[month - 1]) return null;
  return { year, month, day };
}

export function validateSurveyDate(value, today) {
  const parsed = parseCalendarDate(value);
  if (!parsed) return '日期格式错误';
  const todayParsed = parseCalendarDate(today);
  if (!todayParsed) return '日期格式错误';
  const valueKey = parsed.year * 10000 + parsed.month * 100 + parsed.day;
  const todayKey = todayParsed.year * 10000 + todayParsed.month * 100 + todayParsed.day;
  if (valueKey > todayKey) return '调查日期不能晚于今日';
  return '';
}
